import{describe,it,expect}from"vitest";import{heritageThreats,getFilteredThreats}from"../../frontend/heritage-threats/heritage-threats.js";describe("Heritage Threat Monitor",()=>{it("contains minimum 10 endangered heritage sites with complete fields",()=>{expect(Array.isArray(heritageThreats)).toBe(!0),expect(heritageThreats.length).toBeGreaterThanOrEqual(10),heritageThreats.forEach(e=>{expect(e.id).toBeDefined(),expect(e.siteName).toBeDefined(),expect(e.location).toBeDefined(),expect(e.category).toBeDefined(),expect(e.severity).toBeDefined(),expect(e.description).toBeDefined(),expect(e.conservationEfforts).toBeDefined()})}),it("filters threats by category correctly",()=>{const e=getFilteredThreats("","pollution","all");expect(e.length).toBeGreaterThan(0),e.forEach(e=>expect(e.category).toBe("pollution"))}),it("filters threats by severity level correctly",()=>{const e=getFilteredThreats("","all","critical");expect(e.length).toBeGreaterThan(0),e.forEach(e=>expect(e.severity).toBe("critical"))}),it("filters threats by search query string correctly",()=>{const e=getFilteredThreats("Taj Mahal");expect(e.length).toBeGreaterThan(0),expect(e[0].siteName).toContain("Taj Mahal")})});